code.java:
class Solution {
    public int getSum(int a, int b) {
        while (b != 0) { int carry = (a & b) << 1; a ^= b; b = carry; } return a;
    }
}

code.kotlin:
class Solution {
    fun getSum(first: Int, second: Int): Int { var a = first; var b = second; while (b != 0) { val carry = (a and b) shl 1; a = a xor b; b = carry }; return a }
}

